sys_script_include.script:
var AIOrchestrator = Class.create();
AIOrchestrator.prototype = {
initialize: function() {
		this.LOG_PREFIX = '[GlobalTech AI] ';
},
processRequest: function(requestId) {
	var result = {
		success: false,
		requestId: requestId,
		message: '',
		agents: [],
		executionCount: 0
	};
	if (!requestId) {
		result.message = 'AI Request ID is required.';
		return result; 
	}
	var request = new GlideRecord('x_78515_globalte_0_ai_request');

	if(!request.get(requestId)) {
		result.message = 'AI Request not found.';
		return result;
	}
	if (request.getValue('ai_status') != 'new'){
		result.message = 'Request is not in New status.';
		return result;
	}
	request.setValue('ai_status', 'processing');
	request.update();

	var agent = new GlideRecord('x_78515_globalte_0_ai_agent');
	    agent.addQuery('active', true);
		agent.orderBy('agent_name');
		agent.query();
		while(agent.next()) {
			var execution = new GlideRecord('x_78515_globalte_0_ai_execution');

	execution.initialize();
	execution.setValue('execution_id', gs.generateGUID());
	execution.setValue('ai_request', requestId);
	execution.setValue('ai_agent', agent.getUniqueValue());
	execution.setValue('execution_status', 'queued');
	execution.setValue('input_data', request.getValue('request_text') || '');

	var executionId = execution.insert();

	if (executionId) {
		result.executionCount++;
		result.agents.push({
			name: agent.getValue('agent_name'),
			executionId: executionId.tostring(),
			status: 'queued'
		});
	}

}
var auditService = new AIAuditService();
 var auditResult = auditService.logAction({
	agentName: 'AI Orchestrator',
	actionType: 'analysis',
	targetTable: 'x_78515_globalte_0_ai_request',
	targetRecord: requestId,
	beforeValue: 'AI Status: new',
	afterValue: 'AI Status: processing',
	result: 'success'
 });
 result.success = true;
 result.message = 'AI Request processed. Execution records created: ' +
                  result.executionCount;
				  if (!auditResult.success) {
					gs.error(this.LOG_PREFIX + 'Audit logging failed: ' + 
					          auditResult.message);
				  }
return result;
},
	type: 'AIOrchestrator'
};
